402	struct Quantized_Vertices {
403	
404		Quantized_Vertices(float epsilon) : scale(2.0f / epsilon) {
405		}
406	
407		std::tuple<int32_t, int32_t, int32_t> quantize(Vec3 v) {
408			int32_t x = static_cast<int32_t>(std::floor(scale * v.x));
409			int32_t y = static_cast<int32_t>(std::floor(scale * v.y));
410			int32_t z = static_cast<int32_t>(std::floor(scale * v.z));
411			return {x, y, z};
412		}
413	
414		void insert(Vec3 v, uint32_t id) {
415	
416			// Very simple quantization; could probably improve precision by separating out the
417			// fractional part. However, accuracy is not particularly important here: we just want to
418			// be able to match vertices up to a small epsilon.
419	
420			auto q = quantize(v);
421			if (vertices.find(q) != vertices.end()) {
422				inputs_unique = false;
423			}
424			vertices.insert({q, id});
425		}
426	
427		std::optional<uint32_t> find(Vec3 v) {
428	
429			auto [x, y, z] = quantize(v);
430			for (int32_t dx = -1; dx <= 1; dx++) {
431				for (int32_t dy = -1; dy <= 1; dy++) {
432					for (int32_t dz = -1; dz <= 1; dz++) {
433						if (vertices.find({x + dx, y + dy, z + dz}) != vertices.end()) {
434							return vertices.at({x + dx, y + dy, z + dz});
435						}
436					}
437				}
438			}
439			return std::nullopt;
440		}
441	
442		bool all_unique() {
443			if (!inputs_unique) return false;
444			for (auto& [q, _] : vertices) {
445				auto [x, y, z] = q;
446				for (int32_t dx = -1; dx <= 1; dx++) {
447					for (int32_t dy = -1; dy <= 1; dy++) {
448						for (int32_t dz = -1; dz <= 1; dz++) {
449							if (dx == 0 && dy == 0 && dz == 0) continue;
450							if (vertices.find({x + dx, y + dy, z + dz}) != vertices.end()) {
451								return false;
452							}
453						}
454					}
455				}
456			}
457			return true;
458		}
459	
460		float scale;
461		bool inputs_unique = true;
462		std::map<std::tuple<int32_t, int32_t, int32_t>, uint32_t> vertices;
463	};
