466	std::optional<std::string> Test::differs(Halfedge_Mesh const &source, Halfedge_Mesh const &target, CheckExtra check_extra) {
467		//NOTE: check_extra actually ignored for now. Will update!
468	
469		constexpr float epsilon = 0.001f;
470	
