747			vertices.back()->position = v;
748		}
749	
750	
751		std::unordered_map< std::pair< Index, Index >, HalfedgeRef > halfedges; //for quick lookup of halfedges by from/to vertex index
752	
753		uint32_t num_faces = static_cast<uint32_t>(faces_.size());
754		const bool add_corner_normals = corner_normal_idxs.size() >= num_faces;
755		const bool add_corner_uvs = corner_uv_idxs.size() >= num_faces;
756		//helper to add a face (and, later, boundary):
757		auto add_loop = [&](std::vector< Index > const &loop, bool boundary,
758						    std::vector< Index> const &n_loop = std::vector<Index>{}, 
759							std::vector< Index> const &uv_loop = std::vector<Index>{}) {
760			assert(loop.size() >= 3);
761			
762			for (uint32_t j = 0; j < loop.size(); ++j) {
763				//omit adding a face with vertices of the same index, otherwise crashes on cylinder/cone
764				if (loop[j] == loop[(j + 1) % loop.size()]) { return; }
765			}
766	
767			FaceRef face = mesh.emplace_face(boundary);
768			HalfedgeRef prev = mesh.halfedges.end(); //keep track of previous edge around face to set next pointer
769			for (uint32_t i = 0; i < loop.size(); ++i) {
770				Index a = loop[i];
771				Index b = loop[(i + 1) % loop.size()];
772				assert(a != b);
773	
774				HalfedgeRef halfedge = mesh.emplace_halfedge();
775				if (i == 0) face->halfedge = halfedge; //store first edge as face's halfedge pointer
776				halfedge->vertex = vertices[a];
777	
778				//if first to mention vertex, set vertex's halfedge pointer:
779				if (vertices[a]->halfedge == mesh.halfedges.end()) {
780					assert(!boundary); //boundary faces should never be mentioning novel vertices, since they are created second
781					vertices[a]->halfedge = halfedge;
782				}
783				halfedge->face = face;
784	
785				auto inserted = halfedges.emplace(std::make_pair(a,b), halfedge);
786				assert(inserted.second); //if edge mentioned more than once in the same direction, not an oriented, manifold mesh
787	
788				auto twin = halfedges.find(std::make_pair(b,a));
789				if (twin == halfedges.end()) {
790					assert(!boundary); //boundary faces exist only to complete edges so should *always* match
791					//not twinned yet -- create an edge just for this halfedge:
792					EdgeRef edge = mesh.emplace_edge(false);
793					halfedge->edge = edge;
794					edge->halfedge = halfedge;
795				} else {
796					//found a twin -- connect twin pointers and reference its edge:
797					assert(twin->second->twin == mesh.halfedges.end());
798					halfedge->twin = twin->second;
799					halfedge->edge = twin->second->edge;
800					twin->second->twin = halfedge;
801				}
802	
803				if (i != 0) prev->next = halfedge; //set previous halfedge's next pointer
804				prev = halfedge;
805	
806				if(add_corner_normals && i < n_loop.size()) halfedge->corner_normal = corner_normals_[n_loop[i]];
807				if(add_corner_uvs && i < uv_loop.size()) halfedge->corner_uv = corner_uvs_[uv_loop[i]];
808			}
809	
810			prev->next = face->halfedge; //set next pointer for last halfedge to first edge
811		};
