849			loop.pop_back(); //remove duplicated first/last element
850	
851			assert(loop.size() >= 3); //all faces must be non-degenerate
852	
853			//add boundary loop:
854			add_loop(loop, true);
855		}
856	
857		//with boundary faces created, mesh should be ready to go with all edges nicely twinned.
858	
859		//PARANOIA: this should never happen:
860		auto error = mesh.validate();
861		if (error) {
862			std::cerr << "Halfedge_Mesh from_indexed_faces failed validation: " << error->second << std::endl;
863			assert(0);
864		}
865	
866		return mesh;
867	}
